package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Shape interface {
	Name() string
	Corners() int
	DoubleArea() int64
}

type base struct {
	name    string
	corners int
	d       int64
}

func (b base) Name() string      { return b.name }
func (b base) Corners() int      { return b.corners }
func (b base) DoubleArea() int64 { return b.d }

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	var shapes []Shape
	for sc.Scan() {
		f := strings.Fields(sc.Text())
		if len(f) == 0 {
			continue
		}
		n := make([]int64, len(f)-1)
		for i := range n {
			n[i], _ = strconv.ParseInt(f[i+1], 10, 64)
		}
		get := func(i int) int64 {
			if i < len(n) {
				return n[i]
			}
			return 0
		}
		switch f[0] {
		case "square":
			shapes = append(shapes, base{f[0], 4, 2 * get(0) * get(0)})
		case "rect":
			shapes = append(shapes, base{f[0], 4, 2 * get(0) * get(1)})
		case "rtri":
			shapes = append(shapes, base{f[0], 3, get(0) * get(1)})
		case "trap":
			shapes = append(shapes, base{f[0], 4, (get(0) + get(1)) * get(2)})
		}
	}
	var total int64
	best := -1
	for i, s := range shapes {
		fmt.Printf("%s corners=%d area2=%d\n", s.Name(), s.Corners(), s.DoubleArea())
		total += s.DoubleArea()
		if best < 0 || s.DoubleArea() > shapes[best].DoubleArea() {
			best = i
		}
	}
	fmt.Printf("total area2=%d\n", total)
	if best < 0 {
		fmt.Println("largest=none")
	} else {
		fmt.Printf("largest=%s area2=%d\n", shapes[best].Name(), shapes[best].DoubleArea())
	}
}
